import sys
M = 1000000007
def fib(n):
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = (2*b - a) * a % M
        u = (a*a + b*b) % M
        if c == '1':
            a, b = u, (t + u) % M
        else:
            a, b = t, u
    return a
def main():
    out = [str(fib(int(x))) for x in sys.stdin.read().split()]
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
main()
